css:
[data-bz-node="hh"] { background: #020617; overflow: hidden; isolation: isolate; perspective: 2000px; perspective-origin: 20% 50%; }
[data-bz-node="hh"]::before { content: ""; position: absolute; inset: 0; z-index: 1; pointer-events: none;
  background: linear-gradient(90deg, #020617 0%, rgba(2,6,23,.92) 28%, rgba(2,6,23,.55) 52%, rgba(2,6,23,.15) 78%, rgba(2,6,23,0) 100%),
              linear-gradient(180deg, rgba(2,6,23,.75) 0%, rgba(2,6,23,0) 18%, rgba(2,6,23,0) 78%, #020617 100%),
              radial-gradient(60% 70% at 78% 45%, rgba(0,205,253,.18), rgba(0,205,253,0) 70%); }
/* the tilted wall: real tiles in a grid, rotated as one */
[data-bz-section="home-hero"] [data-bz-node="hh-wall"] { position: absolute; top: 50%; left: 30%; width: 1050px; margin: 0; display: grid; grid-template-columns: repeat(8, 120px); grid-auto-rows: 90px; grid-auto-flow: dense; gap: 10px;
  transform: translateY(-50%) rotateY(-24deg) rotateX(3deg); transform-origin: left center; pointer-events: none; z-index: 0; }
[data-bz-node="hh-wall"] > .bz-col { position: relative; grid-column: auto; border-radius: 5px; overflow: hidden; background: #0a2c46; min-width: 0; }
[data-bz-node="hh-wall"] > .bz-col:nth-child(1),
[data-bz-node="hh-wall"] > .bz-col:nth-child(4),
[data-bz-node="hh-wall"] > .bz-col:nth-child(8),
[data-bz-node="hh-wall"] > .bz-col:nth-child(11),
[data-bz-node="hh-wall"] > .bz-col:nth-child(15),
[data-bz-node="hh-wall"] > .bz-col:nth-child(17),
[data-bz-node="hh-wall"] > .bz-col:nth-child(22),
[data-bz-node="hh-wall"] > .bz-col:nth-child(25),
[data-bz-node="hh-wall"] > .bz-col:nth-child(27),
[data-bz-node="hh-wall"] > .bz-col:nth-child(29),
[data-bz-node="hh-wall"] > .bz-col:nth-child(31),
[data-bz-node="hh-wall"] > .bz-col:nth-child(33),
[data-bz-node="hh-wall"] > .bz-col:nth-child(35),
[data-bz-node="hh-wall"] > .bz-col:nth-child(37),
[data-bz-node="hh-wall"] > .bz-col:nth-child(39),
[data-bz-node="hh-wall"] > .bz-col:nth-child(41) { grid-row: span 2; }
[data-bz-node="hh-wall"] .bz-block { position: static; }
[data-bz-node="hh-wall"] img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; border-radius: 0; background: linear-gradient(160deg, #0a5a86 0%, #0a2c46 55%, #240140 100%); }
[data-bz-node="hh-wall"] [data-bz-node^="hh-tile-name"] { position: absolute; left: 8px; right: 8px; bottom: 7px; z-index: 1; }
[data-bz-node="hh-wall"] [data-bz-node^="hh-tile-name"].bz-block p { margin: 0; font-family: var(--font-heading); font-weight: 700; font-size: 12px; line-height: .95; text-transform: uppercase; color: #f4fbff; text-shadow: 0 2px 8px rgba(0,0,0,.8); }
[data-bz-node="hh-copy"] { position: relative; z-index: 2; max-width: var(--pip-w); margin: 0 auto; padding: 140px var(--pip-pad) 90px; box-sizing: border-box; }
[data-bz-node="hh-eyebrow"].bz-block p { margin: 0 0 26px; line-height: normal; font-family: var(--font-heading); font-weight: 500; font-size: 13px; letter-spacing: .34em; text-transform: uppercase; color: #00cdfd; }
[data-bz-node="hh-intro"].bz-block p { max-width: 560px; margin: 28px 0 0; font-weight: 300; font-size: 19px; line-height: 1.55; color: #9fb4c6; }
@media (max-width: 1100px) { [data-bz-section="home-hero"] [data-bz-node="hh-wall"] { left: 45%; opacity: .55; } }
@media (max-width: 640px) { [data-bz-section="home-hero"] [data-bz-node="hh-wall"] { left: 20%; opacity: .4; } [data-bz-node="hh-copy"] { padding-block: 120px 70px; } [data-bz-node="hh-intro"].bz-block p { font-size: 17px; } }
/* bubbles are decorative and only exist once the script has run */
.pip-bubbles { position: absolute; top: 0; bottom: 0; left: 0; right: 0; pointer-events: none; overflow: hidden; z-index: 2; }
.pip-bubble { position: absolute; border-radius: 50%; animation: pip-rise linear infinite; }
@keyframes pip-rise { 0% { transform: translateY(0) translateX(0); opacity: 0; } 12% { opacity: .55; } 88% { opacity: .35; } 100% { transform: translateY(-105vh) translateX(24px); opacity: 0; } }
